#!/usr/bin/env bash
# Generated by Workspace Tree Conductor Stack
set -e

echo -e "\033[1;36m🚀 Starting Local Dev Stack for Automation...\033[0m"
PIDS=()

cleanup() {
    echo -e "\n\033[1;31m🛑 Shutting down all services cleanly...\033[0m"
    for pid in "${PIDS[@]}"; do
        if kill -0 "$pid" 2>/dev/null; then
            kill "$pid" 2>/dev/null || true
        fi
    done
    wait 2>/dev/null
    echo -e "\033[0;90mAll processes terminated.\033[0m"
}
trap cleanup SIGINT SIGTERM EXIT

echo -e "\033[1;33m  [+] Starting Dev Server...\033[0m"
npm run dev &
PIDS+=($!)

echo -e "\033[1;32m✅ All services running! Press Ctrl+C to stop all.\033[0m"
wait